#' Storage Utilities for Simulation Results
#'
#' Functions for initializing and managing storage structures
#' for simulation results across different sample sizes and models.

#' Initialize results storage structure
#'
#' @param sample_sizes Numeric vector of sample sizes
#' @param target_models Character vector of model names
#' @param metrics Character vector of metric names
#' @param predictor_config List with predictor configuration
#' @return Nested list structure for storing results
#' @noRd
initialize_results_storage <- function(sample_sizes, target_models, metrics, predictor_config) {
  n_sizes <- length(sample_sizes)
  storage <- list()

  for (model in target_models) {
    storage[[model]] <- list()
    for (metric in metrics) {
      storage[[model]][[metric]] <- data.frame(
        sample_size = sample_sizes,
        mean = rep(NA_real_, n_sizes),
        sd = rep(NA_real_, n_sizes),
        median = rep(NA_real_, n_sizes),
        q025 = rep(NA_real_, n_sizes),
        q975 = rep(NA_real_, n_sizes),
        min = rep(NA_real_, n_sizes),
        max = rep(NA_real_, n_sizes),
        n_success = rep(NA_integer_, n_sizes),
        n_failed = rep(NA_integer_, n_sizes)
      )
    }
  }

  return(storage)
}

#' Initialize storage for simulations at one sample size
#'
#' @param n_simulations Integer number of simulations
#' @param target_models Character vector of model names
#' @param metrics Character vector of metric names
#' @return Nested list for storing individual simulation results
#' @noRd
initialize_sim_storage <- function(n_simulations, target_models, metrics) {
  storage <- list()
  for (model in target_models) {
    storage[[model]] <- list()
    for (metric in metrics) {
      storage[[model]][[metric]] <- rep(NA_real_, n_simulations)
    }
  }
  return(storage)
}

#' Aggregate results across simulations
#'
#' @param results Main results storage structure
#' @param sim_results_n Results from simulations at current sample size
#' @param n Current sample size
#' @param i_size Index of current sample size
#' @return Updated results structure with aggregated statistics
#' @noRd
aggregate_results <- function(results, sim_results_n, n, i_size) {
  for (model in names(sim_results_n)) {
    for (metric in names(sim_results_n[[model]])) {
      values <- sim_results_n[[model]][[metric]]
      total <- length(values)
      values <- values[!is.na(values) & is.finite(values)]  # Remove NA and Inf
      results[[model]][[metric]][i_size, "n_success"] <- length(values)
      results[[model]][[metric]][i_size, "n_failed"] <- total - length(values)

      if (length(values) > 0) {
        results[[model]][[metric]][i_size, "mean"] <- mean(values, na.rm = TRUE)
        results[[model]][[metric]][i_size, "sd"] <- sd(values, na.rm = TRUE)
        results[[model]][[metric]][i_size, "median"] <- median(values, na.rm = TRUE)
        results[[model]][[metric]][i_size, "q025"] <- quantile(values, 0.025, na.rm = TRUE)
        results[[model]][[metric]][i_size, "q975"] <- quantile(values, 0.975, na.rm = TRUE)
        results[[model]][[metric]][i_size, "min"] <- min(values, na.rm = TRUE)
        results[[model]][[metric]][i_size, "max"] <- max(values, na.rm = TRUE)
      }
    }
  }
  return(results)
}

#' Version tag for reusable simulation-table keys
#'
#' Increment this value when a change makes previously cached aggregate results
#' methodologically incompatible with the current framework.
#'
#' @return Character cache schema version.
#' @noRd
simulation_table_version <- function() {
  "2026-10-13-v2"
}

#' Create a stable key for one model simulation configuration
#'
#' Sample size and metric are deliberately excluded because they are stored as
#' table columns. All inputs that affect generated data, resampling, or model
#' fitting are included.
#'
#' @param data_generation Data generation configuration.
#' @param predictor_config Predictor configuration.
#' @param reference_model Reference model name.
#' @param model Target model name.
#' @param model_options Resolved options for the target model.
#' @param n_simulations Number of simulations.
#' @param cv_folds Number of CV folds.
#' @param cv_repeats Number of CV repeats.
#' @param seed Simulation seed.
#' @param validation_strategy Random or ordered validation.
#' @param order_var Optional ordering column.
#' @return MD5 key as a character scalar.
#' @noRd
create_simulation_key <- function(data_generation, predictor_config,
                                  reference_model, model, model_options,
                                  n_simulations, cv_folds, cv_repeats, seed,
                                  validation_strategy, order_var) {
  cache_safe_options <- lapply(model_options, function(option) {
    if (inherits(option, "family")) {
      return(list(family = option$family, link = option$link))
    }
    option
  })

  key_input <- list(
    table_version = simulation_table_version(),
    data_generation = data_generation,
    predictor_config = predictor_config,
    reference_model = reference_model,
    model = model,
    model_options = cache_safe_options,
    n_simulations = n_simulations,
    cv_folds = cv_folds,
    cv_repeats = if (identical(validation_strategy, "ordered")) 1L else cv_repeats,
    seed = seed,
    validation_strategy = validation_strategy,
    order_var = order_var
  )

  key_file <- tempfile(fileext = ".rds")
  on.exit(unlink(key_file), add = TRUE)
  saveRDS(key_input, key_file, version = 2, compress = FALSE)
  unname(tools::md5sum(key_file))
}

#' Create cache keys for selected target models
#'
#' @param target_models Canonical target model names.
#' @param model_options Named list of per-model option overrides.
#' @param ... Configuration arguments forwarded to create_simulation_key().
#' @return Named character vector keyed by model.
#' @noRd
create_simulation_keys <- function(target_models, model_options = list(), ...) {
  keys <- vapply(target_models, function(model) {
    options <- resolve_model_options(model, model_options[[model]] %||% list())
    create_simulation_key(model = model, model_options = options, ...)
  }, character(1))
  stats::setNames(keys, target_models)
}

#' Read and validate a reusable simulation table
#'
#' @param lookup_table NULL, a data frame, a sample_size_simulation object, or a
#'   path to a CSV file created by results_to_simulation_table().
#' @return Validated data frame or NULL.
#' @export
load_simulation_table <- function(lookup_table = NULL) {
  if (is.null(lookup_table)) return(NULL)

  if (inherits(lookup_table, "sample_size_simulation")) {
    lookup_table <- lookup_table$simulation_table
  } else if (is.character(lookup_table) && length(lookup_table) == 1) {
    if (!file.exists(lookup_table)) {
      stop("lookup_table file not found: ", lookup_table)
    }
    lookup_table <- utils::read.csv(
      lookup_table, stringsAsFactors = FALSE, check.names = FALSE
    )
  }

  if (!is.data.frame(lookup_table)) {
    stop("lookup_table must be a data frame, simulation result, or CSV path")
  }

  required <- c(
    "simulation_key", "model", "metric", "sample_size", "mean", "sd",
    "median", "q025", "q975", "min", "max"
  )
  missing_columns <- setdiff(required, names(lookup_table))
  if (length(missing_columns) > 0) {
    stop(
      "lookup_table is missing required columns: ",
      paste(missing_columns, collapse = ", ")
    )
  }

  lookup_table$model <- vapply(
    lookup_table$model, normalize_model_type, character(1)
  )
  lookup_table$metric <- as.character(lookup_table$metric)
  lookup_table$simulation_key <- as.character(lookup_table$simulation_key)
  lookup_table$sample_size <- as.numeric(lookup_table$sample_size)
  if (any(!is.na(lookup_table$simulation_key) & !nzchar(lookup_table$simulation_key)) ||
      anyNA(lookup_table$metric) || any(!lookup_table$metric %in% supported_metrics()) ||
      anyNA(lookup_table$sample_size) || any(!is.finite(lookup_table$sample_size)) ||
      any(lookup_table$sample_size < 2 | lookup_table$sample_size != floor(lookup_table$sample_size))) {
    stop("lookup_table contains invalid cache keys, metrics, or sample sizes")
  }
  statistics <- c("mean", "sd", "median", "q025", "q975", "min", "max")
  if (any(!vapply(lookup_table[statistics], is.numeric, logical(1)))) {
    stop("lookup_table summary columns must be numeric")
  }
  identifiers <- lookup_table[c("simulation_key", "model", "metric", "sample_size")]
  if (anyDuplicated(identifiers)) {
    stop("lookup_table contains duplicate model/metric/sample-size cache rows")
  }
  lookup_table
}

#' Restore complete model/sample-size rows from a simulation table
#'
#' A model is restored only when every requested metric is present for the exact
#' configuration key and sample size. This prevents partial or mismatched cache
#' entries from being treated as complete results.
#'
#' @param results Nested result storage.
#' @param lookup_table Validated simulation table or NULL.
#' @param simulation_keys Named keys by model.
#' @param target_models Target models.
#' @param metrics Requested metrics.
#' @param n Current sample size.
#' @param i_size Current sample-size row index.
#' @return List containing updated results and cached model names.
#' @noRd
restore_results_from_table <- function(results, lookup_table, simulation_keys,
                                       target_models, metrics, n, i_size) {
  if (is.null(lookup_table) || nrow(lookup_table) == 0) {
    return(list(results = results, cached_models = character(0)))
  }

  cached_models <- character(0)
  statistic_columns <- c("mean", "sd", "median", "q025", "q975", "min", "max")

  for (model in target_models) {
    model_rows <- lookup_table[
      lookup_table$simulation_key %in% simulation_keys[[model]] &
        lookup_table$model == model &
        lookup_table$sample_size == n,
      , drop = FALSE
    ]

    if (!all(metrics %in% model_rows$metric)) next

    for (metric in metrics) {
      row <- model_rows[model_rows$metric == metric, , drop = FALSE]
      row <- row[nrow(row), , drop = FALSE]
      for (column in statistic_columns) {
        results[[model]][[metric]][i_size, column] <- as.numeric(row[[column]])
      }
      for (column in intersect(c("n_success", "n_failed"), names(row))) {
        results[[model]][[metric]][i_size, column] <- as.integer(row[[column]])
      }
    }
    cached_models <- c(cached_models, model)
  }

  list(results = results, cached_models = cached_models)
}

#' Convert nested simulation results to a reusable long-form table
#'
#' @param results Nested results object (the $results element of a simulation).
#' @param simulation_keys Optional named character vector keyed by model.
#' @return Long-form data frame with one row per model, metric, and sample size.
#' @export
results_to_simulation_table <- function(results, simulation_keys = NULL) {
  rows <- list()
  row_index <- 1L

  for (model in names(results)) {
    for (metric in names(results[[model]])) {
      metric_table <- results[[model]][[metric]]
      metric_table$model <- model
      metric_table$metric <- metric
      metric_table$simulation_key <- if (is.null(simulation_keys)) {
        NA_character_
      } else {
        unname(simulation_keys[[model]])
      }
      rows[[row_index]] <- metric_table
      row_index <- row_index + 1L
    }
  }

  output <- do.call(rbind, rows)
  preferred <- c(
    "simulation_key", "model", "metric", "sample_size", "mean", "sd",
    "median", "q025", "q975", "min", "max", "efficiency"
  )
  output <- output[, c(intersect(preferred, names(output)),
                       setdiff(names(output), preferred)), drop = FALSE]
  rownames(output) <- NULL
  output
}

#' Combine reusable simulation tables without duplicate cache rows
#'
#' Rows from `new_table` replace matching rows from `existing_table`.
#'
#' @param existing_table Existing table, simulation result, CSV path, or NULL.
#' @param new_table New simulation table.
#' @return Combined de-duplicated simulation table.
#' @export
merge_simulation_tables <- function(existing_table, new_table) {
  existing_table <- load_simulation_table(existing_table)
  new_table <- load_simulation_table(new_table)
  if (is.null(existing_table)) return(new_table)
  if (is.null(new_table)) return(existing_table)

  all_columns <- union(names(existing_table), names(new_table))
  for (column in setdiff(all_columns, names(existing_table))) {
    existing_table[[column]] <- NA
  }
  for (column in setdiff(all_columns, names(new_table))) {
    new_table[[column]] <- NA
  }
  combined <- rbind(
    existing_table[, all_columns, drop = FALSE],
    new_table[, all_columns, drop = FALSE]
  )
  row_id <- paste(
    combined$simulation_key, combined$model, combined$metric,
    combined$sample_size, sep = "\r"
  )
  combined <- combined[!duplicated(row_id, fromLast = TRUE), , drop = FALSE]
  rownames(combined) <- NULL
  combined
}

#' Read recommendations directly from a completed simulation table
#'
#' @param simulation_table Reusable simulation table or CSV path.
#' @param efficiency_threshold Required efficiency threshold.
#' @param simulation_key Optional key used to select one scenario.
#' @return Data frame of minimum sample sizes by model and metric.
#' @export
recommend_from_simulation_table <- function(simulation_table,
                                             efficiency_threshold = 0.95,
                                             simulation_key = NULL) {
  validate_threshold(efficiency_threshold)
  table <- load_simulation_table(simulation_table)
  if (is.null(table)) stop("simulation_table must not be NULL")
  if (!"efficiency" %in% names(table)) {
    stop("simulation_table must contain an efficiency column")
  }
  if (!is.null(simulation_key)) {
    table <- table[table$simulation_key %in% simulation_key, , drop = FALSE]
  }
  if (nrow(table) == 0) stop("No matching rows found in simulation_table")

  groups <- split(
    table,
    paste(table$simulation_key, table$model, table$metric, sep = "\r")
  )
  recommendations <- lapply(groups, function(group) {
    group <- group[order(group$sample_size), , drop = FALSE]
    qualifying <- which(group$efficiency >= efficiency_threshold)
    data.frame(
      simulation_key = group$simulation_key[1],
      model = group$model[1],
      metric = group$metric[1],
      min_sample_size = if (length(qualifying) == 0) NA_real_ else
        group$sample_size[qualifying[1]],
      stringsAsFactors = FALSE
    )
  })

  output <- do.call(rbind, recommendations)
  rownames(output) <- NULL
  output
}

#' Save simulation results to files
#'
#' @param results Main results object
#' @param min_sample_sizes Minimum sample size recommendations
#' @param validation_results Validation results (if any)
#' @param output_path Directory path for saving
#' @param timestamp Timestamp string for file naming
#' @param simulation_table Optional reusable long-form table
#' @noRd
save_simulation_results <- function(results, min_sample_sizes, validation_results,
                                   output_path, timestamp,
                                   simulation_table = NULL) {
  dir.create(output_path, showWarnings = FALSE, recursive = TRUE)

  # Save detailed results for each model and metric
  for (model in names(results)) {
    for (metric in names(results[[model]])) {
      filename <- file.path(output_path,
                           paste0("results_", model, "_", metric, "_", timestamp, ".csv"))
      write.csv(results[[model]][[metric]], filename, row.names = FALSE)
    }
  }

  # Save minimum sample size recommendations
  if (!is.null(min_sample_sizes) && length(min_sample_sizes) > 0) {
    min_sizes_df <- data.frame(
      model = rep(names(min_sample_sizes), each = length(min_sample_sizes[[1]])),
      metric = rep(names(min_sample_sizes[[1]]), length(min_sample_sizes)),
      min_sample_size = unlist(min_sample_sizes)
    )
    write.csv(min_sizes_df,
             file.path(output_path, paste0("min_sample_sizes_", timestamp, ".csv")),
             row.names = FALSE)
  }

  # Save validation results if available
  if (!is.null(validation_results)) {
    saveRDS(validation_results,
           file.path(output_path, paste0("validation_", timestamp, ".rds")))
  }

  if (!is.null(simulation_table)) {
    utils::write.csv(
      simulation_table,
      file.path(output_path, paste0("simulation_table_", timestamp, ".csv")),
      row.names = FALSE
    )
  }

  # Save full results object
  saveRDS(results,
         file.path(output_path, paste0("full_results_", timestamp, ".rds")))

  message("Results saved to: ", output_path)
}

#' Load saved simulation results
#'
#' @param output_path Directory path where results are saved
#' @param timestamp Optional timestamp to load specific results
#' @return List with loaded results
#' @export
load_simulation_results <- function(output_path, timestamp = NULL) {
  if (is.null(timestamp)) {
    # Find most recent results
    files <- list.files(output_path, pattern = "full_results_.*\\.rds", full.names = TRUE)
    if (length(files) == 0) {
      stop("No results files found in ", output_path)
    }
    file_to_load <- files[order(file.info(files)$mtime, decreasing = TRUE)[1]]
  } else {
    file_to_load <- file.path(output_path, paste0("full_results_", timestamp, ".rds"))
  }

  if (!file.exists(file_to_load)) {
    stop("Results file not found: ", file_to_load)
  }

  results <- readRDS(file_to_load)
  message("Loaded results from: ", file_to_load)
  return(results)
}
